	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given refill rate (tokens per second),
// burst capacity, and clock. If clock is nil, the real clock is used.
func New(rate, burst float64, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  burst,
		tokens: burst,
		last:   clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now,
// refilling the bucket first. It does not wait.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}
