// Package ratelimit implements a concurrency-safe token-bucket rate limiter
// with an injectable clock for deterministic testing.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time. time.Now satisfies this interface.
type Clock interface {
	Now() time.Time
}

// realClock adapts time.Now to Clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with New; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	capacity  int
	rate      float64 // tokens per second
	tokens    float64
	lastRefil time.Time
	clock     Clock
}

var (
	ErrCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrRate     = errors.New("ratelimit: rate must be > 0")
	ErrClock    = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter with the given burst capacity and refill rate
// (tokens per second), starting full. capacity and rate must be positive.
func New(capacity int, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable Clock, primarily for tests.
func NewWithClock(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrCapacity
	}
	if rate <= 0 {
		return nil, ErrRate
	}
	if clock == nil {
		return nil, ErrClock
	}
	now := clock.Now()
	return &Limiter{
		capacity:  capacity,
		rate:      rate,
		tokens:    float64(capacity),
		lastRefil: now,
		clock:     clock,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available, consuming them if so.
// It refills the bucket based on elapsed time before deciding.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefil)
	if elapsed > 0 {
		l.tokens += elapsed.Seconds() * l.rate
		if l.tokens > float64(l.capacity) {
			l.tokens = float64(l.capacity)
		}
		l.lastRefil = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	elapsed := now.Sub(l.lastRefil)
	t := l.tokens + elapsed.Seconds()*l.rate
	if t > float64(l.capacity) {
		t = float64(l.capacity)
	}
	return t
}
