	return l.AllowN(l.clock.Now(), 1)
}

// Tokens returns the number of tokens currently available (advanced to now).
func (l *Limiter) Tokens() float64 {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		t := l.tokens + elapsed*l.rate
		if t > l.capacity {
			t = l.capacity
		}
		return t
	}
	return l.tokens
}
