// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the wall clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production Clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created with NewLimiter and must not be copied after use.
type Limiter struct {
	mu       sync.Mutex
	capacity int      // max tokens
	tokens   float64  // current tokens
	rate     float64  // tokens per second
	last     time.Time // last refill time
	clock    Clock
}

// ErrInvalidConfig is returned by NewLimiter for invalid arguments.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be positive")

// NewLimiter creates a Limiter with a full bucket of capacity tokens,
// refilled at rate tokens per second.
func NewLimiter(capacity int, rate float64) (*Limiter, error) {
	return NewLimiterWithClock(capacity, rate, RealClock)
}

// NewLimiterWithClock is like NewLimiter but uses the given Clock.
func NewLimiterWithClock(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = RealClock
	}
	now := clock.Now()
	return &Limiter{
		capacity: capacity,
		tokens:   float64(capacity),
		rate:     rate,
		last:     now,
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.capacity) {
			l.tokens = float64(l.capacity)
		}
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
