	l, _ := NewLimiterWithClock(100, 1, clk)
	const goroutines, perG = 50, 10
	allowed := make(chan int, goroutines)
	var mu struct {
		sync.Mutex
		n int
	}
	for i := 0; i < goroutines; i++ {
		go func() {
			ok := 0
			for j := 0; j < perG; j++ {
				if l.AllowN(1) {
					ok++
				}
			}
			mu.Lock()
			mu.n += ok
			mu.Unlock()
			allowed <- ok
		}()
	}
	total := 0
	for i := 0; i < goroutines; i++ {
		total += <-allowed
	}
	if total > 100 {
		t.Fatalf("allowed %d, exceeds capacity 100", total)
	}
}

func base() time.Time {
	return time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)
}
